        description <<~TEXT
        Unknown. Records the supported security standards if "other" is selected in field 098
        TEXT
      end

      argument :security_standard_ids, [::GraphQL::Types::ID, { null: false }], required: false,
        loads: ::Types::SecurityStandardType, as: :security_standards do
        description <<~TEXT
