        TEXT

        validates allow_null: false
      end

      argument :service_provider_free_input, String, required: false do
        description <<~TEXT
        Registered service providers — Free Input. Free input value that is imported and exported via EOI
        TEXT
      end

      argument :service_providers, [::Types::StructuredServiceProviderInputType, { null: false }], required: false do
