        Registered service providers. Link to a public registry of approved third party service providers or
        to a description of services available.
        TEXT

        validates allow_null: false
      end

      argument :service_summary, String, required: false do
        description <<~TEXT
        Service summary. Narrative description of the service.
        TEXT
      end

      argument :shareholders, ::GraphQL::Types::Boolean, required: false do
