        TEXT

        validates allow_null: false
      end

      argument :staffing_full_time_id, ::GraphQL::Types::ID, required: false,
        loads: ::Types::StaffingType, as: :staffing_full_time do
        description <<~TEXT
        Staff: Full-time. The current number of full-time equivalent (FTE) compensated employees.
        TEXT
      end

      argument :staffing_volunteer_id, ::GraphQL::Types::ID, required: false,
        loads: ::Types::StaffingType, as: :staffing_volunteer do
        description <<~TEXT
        Staff: Volunteer. The current number of full-time equivalent (FTE) uncompensated volunteers whose
        work serves an essential business function.
        TEXT
      end

      argument :status_certification_ids, [::GraphQL::Types::ID, { null: false }], required: false,
        loads: ::Types::StatusCertificationType, as: :status_certifications do
        description <<~TEXT
        Status certifications. Certifications, seals, or other formal recognition of the infrastructure's
        adherence to community standards or best practices.
        TEXT

        validates allow_null: false
      end

      argument :top_granting_institution_free_input, String, required: false do
        description <<~TEXT
        Top granting institutions — Free Input. Free input value that is imported and exported via EOI
        TEXT
      end

      argument :top_granting_institutions, [::Types::StructuredInstitutionInputType, { null: false }], required: false do
        description <<~TEXT
        Top granting institutions. List of organizations that have provided the greatest amount of grant
        funds to the service or provider in the past year.
        TEXT

        validates allow_null: false
      end

      argument :total_assets, String, required: false do
        description <<~TEXT
        Total assets in local currency. The value of everything that the organization owns at the end of the
        year, such as cash, investments, property, equipment, etc. For US-based non-profits, Part X, line 16
        from an IRS Form 990.
        TEXT

        validates allow_null: false
      end

      argument :total_contributions, String, required: false do
        description <<~TEXT
        Total contributions in local currency. The amount of money that the organization received from
        donors and grantmakers during the year. For US-based non-profits, Part VIII, line 1h from an IRS
        Form 990.
        TEXT

        validates allow_null: false
      end

      argument :total_liabilities, String, required: false do
        description <<~TEXT
        Total liabilities in local currency. The amount of money that the organization owes to others at the
        end of the year, such as loans, mortgages, accounts payable, deferred revenue, etc. For US-based
        non-profits, Part X, line 26 from an IRS Form 990.
        TEXT

        validates allow_null: false
      end

      argument :user_contribution_other, String, required: false do
        description <<~TEXT
        Unknown. Records additional contribution opportunities if "other" is selected in field 040
        TEXT
      end

      argument :user_contribution_ids, [::GraphQL::Types::ID, { null: false }], required: false,
        loads: ::Types::UserContributionType, as: :user_contributions do
        description <<~TEXT
        User contribution opportunities. Inventory of ways in which users can meaningfully contribute to the
        development or delivery of the service.
        TEXT

        validates allow_null: false
      end

      argument :user_documentation, ::Types::UserDocumentationImplementationInputType, required: false do
        description <<~TEXT
        User documentation. Actual implementation property for User documentation
        TEXT

        validates allow_null: false
      end

      argument :user_documentation_implementation, ::Types::ImplementationStatusType, required: false do
        description <<~TEXT
        Technical user documentation. Public documentation that meaningfully describes the process users to
