        those services not reliant on client installs, documentation that meaningfully describes how users
        perform tasks on the platform to utilise the service.
        TEXT

        validates allow_null: false
      end

      argument :values_framework_ids, [::GraphQL::Types::ID, { null: false }], required: false,
        loads: ::Types::ValuesFrameworkType, as: :values_frameworks do
        description <<~TEXT
        Engagement with values frameworks. Publicly available documentation of engagement or self-evaluation
        using community-developed values assessments. These might include Principles of Open Scholarly
        Infrastructure (POSI), FOREST Framework, TRUST Principles for Digital Repositories.
        TEXT

        validates allow_null: false
      end

      argument :web_accessibility, ::Types::WebAccessibilityImplementationInputType, required: false do
        description <<~TEXT
        Web accessibility. Actual implementation property for Web accessibility
        TEXT

        validates allow_null: false
      end

      argument :web_accessibility_applicability_ids, [::GraphQL::Types::ID, { null: false }], required: false,
        loads: ::Types::AccessibilityScopeType, as: :web_accessibility_applicabilities do
        description <<~TEXT
        Web accessibility statement applicability. Indication of whether the web accessibility statement
        applies solely to a service or provider's website or to the tool itself.
        TEXT

        validates allow_null: false
      end

      argument :web_accessibility_implementation, ::Types::ImplementationStatusType, required: false do
        description <<~TEXT
        Web accessibility statement. Public statement describing the organization’s commitment and actions
        to making their sites accessible to all users regardless of their abilities.
        TEXT

        validates allow_null: false
      end

      argument :website, String, required: false do
        description <<~TEXT
        Website. Primary web presence of the service.
        TEXT
      end
    end
  end
